import{_ as e,c as i,ag as l,o}from"./chunks/framework.BMGgE9iy.js";const b=JSON.parse('{"title":"0.15.1","description":"","frontmatter":{"outline":"deep","comments":false,"showVersion":false},"headers":[],"relativePath":"update/0.15.1-description.md","filePath":"update/0.15.1-description.md"}'),r={name:"update/0.15.1-description.md"};function t(d,a,n,h,c,s){return o(),i("div",null,a[0]||(a[0]=[l('<h1 id="_0-15-1" tabindex="-1"><code>0.15.1</code> <a class="header-anchor" href="#_0-15-1" aria-label="Permalink to &quot;`0.15.1`&quot;">​</a></h1><p>2025/1/20，<code>0.15.1</code> 發佈，自上一個版本來歷時 5 個月，共有 162 位貢獻者參與，進行了 647 次提交！</p><p>Zig 官方團隊直接從 <code>0.14.0</code> 跨越到了 <code>0.15.1</code>。在默認選擇 Zig 的 x86 後端後，調試編譯速度提高了 <strong>5</strong> 倍；正在開發的 aarch64 後端也緊隨其後。同時，隨著 <code>Writergate</code> 事件以及一系列語言變更和標準庫的調整，<strong>大量</strong> API 有破壞性更改；這預示著 async/await 即將重生；也是語言穩定化的最後關頭。</p><h2 id="編譯器重大改進" tabindex="-1">編譯器重大改進 <a class="header-anchor" href="#編譯器重大改進" aria-label="Permalink to &quot;編譯器重大改進&quot;">​</a></h2><h3 id="x86-後端性能突破" tabindex="-1">x86 後端性能突破 <a class="header-anchor" href="#x86-後端性能突破" aria-label="Permalink to &quot;x86 後端性能突破&quot;">​</a></h3><p><strong>調試模式</strong>的編譯速度提高了 <strong>5</strong> 倍；這是本次更新最顯著的性能改進。x86 後端現在是<strong>調試模式</strong>的默認選擇，為縮短開發週期提供了強有力的支持。</p><h3 id="aarch64-後端開發進展" tabindex="-1">aarch64 後端開發進展 <a class="header-anchor" href="#aarch64-後端開發進展" aria-label="Permalink to &quot;aarch64 後端開發進展&quot;">​</a></h3><p>aarch64 後端的開發也在穩步推進，持續優化 ARM 平臺支持，為多架構開發提供更好的體驗。</p><h3 id="增量編譯功能增強" tabindex="-1">增量編譯功能增強 <a class="header-anchor" href="#增量編譯功能增強" aria-label="Permalink to &quot;增量編譯功能增強&quot;">​</a></h3><p>增量編譯功能得到了進一步優化，現在支持：</p><ul><li>與文件系統監視結合使用</li><li>僅檢查編譯錯誤模式</li><li>更快的重建速度</li></ul><h3 id="多線程代碼生成" tabindex="-1">多線程代碼生成 <a class="header-anchor" href="#多線程代碼生成" aria-label="Permalink to &quot;多線程代碼生成&quot;">​</a></h3><p>編譯器現已支持多線程代碼生成，能夠充分利用多核 CPU 的性能優勢。</p><h2 id="語言特性重大調整" tabindex="-1">語言特性重大調整 <a class="header-anchor" href="#語言特性重大調整" aria-label="Permalink to &quot;語言特性重大調整&quot;">​</a></h2><h3 id="移除-usingnamespace-關鍵字" tabindex="-1">移除 <code>usingnamespace</code> 關鍵字 <a class="header-anchor" href="#移除-usingnamespace-關鍵字" aria-label="Permalink to &quot;移除 `usingnamespace` 關鍵字&quot;">​</a></h3><p>這是一個<strong>破壞性變更</strong>，<code>usingnamespace</code> 關鍵字被完全移除。所有使用 <code>usingnamespace</code> 的代碼都需要重寫，建議採用顯式導入方式替代，以提高代碼可讀性和可維護性。</p><h3 id="移除異步關鍵字" tabindex="-1">移除異步關鍵字 <a class="header-anchor" href="#移除異步關鍵字" aria-label="Permalink to &quot;移除異步關鍵字&quot;">​</a></h3><p><code>async</code> 和 <code>await</code> 關鍵字已被移除，當前異步編程模型也隨之取消，為未來新的異步方案做準備。這預示著 Zig 協程 的重生。</p><h3 id="增強對非窮盡枚舉的-switch-支持" tabindex="-1">增強對非窮盡枚舉的 <code>switch</code> 支持 <a class="header-anchor" href="#增強對非窮盡枚舉的-switch-支持" aria-label="Permalink to &quot;增強對非窮盡枚舉的 `switch` 支持&quot;">​</a></h3><p>新增對非窮盡枚舉使用 <code>switch</code> 語句的支持，提高了枚舉處理的靈活性，能夠更好地處理未知枚舉值，增強代碼的健壯性。</p><h3 id="擴展布爾向量運算符支持" tabindex="-1">擴展布爾向量運算符支持 <a class="header-anchor" href="#擴展布爾向量運算符支持" aria-label="Permalink to &quot;擴展布爾向量運算符支持&quot;">​</a></h3><p>布爾向量現在支持更多運算符，包括邏輯運算和比較運算。</p><h3 id="內聯彙編-類型化的破壞描述符" tabindex="-1">內聯彙編：類型化的破壞描述符 <a class="header-anchor" href="#內聯彙編-類型化的破壞描述符" aria-label="Permalink to &quot;內聯彙編：類型化的破壞描述符&quot;">​</a></h3><p>內聯彙編現在支持類型化的 <code>clobber</code> 列表，提供了更好的類型安全保證。</p><h3 id="指針轉換能力增強" tabindex="-1">指針轉換能力增強 <a class="header-anchor" href="#指針轉換能力增強" aria-label="Permalink to &quot;指針轉換能力增強&quot;">​</a></h3><p><code>@ptrCast</code> 現在允許從單項指針轉換為切片，提供了更大的靈活性。</p><h3 id="調整-undefined-運算規則" tabindex="-1">調整 <code>undefined</code> 運算規則 <a class="header-anchor" href="#調整-undefined-運算規則" aria-label="Permalink to &quot;調整 `undefined` 運算規則&quot;">​</a></h3><p>對 <code>undefined</code> 值的算術運算規則有所調整，任何與 <code>undefined</code> 的運算結果都將返回 <code>undefined</code>。</p><h3 id="加強有損轉換檢測" tabindex="-1">加強有損轉換檢測 <a class="header-anchor" href="#加強有損轉換檢測" aria-label="Permalink to &quot;加強有損轉換檢測&quot;">​</a></h3><p>對於可能導致精度損失的整數到浮點數轉換，編譯器會視為錯誤。</p><h2 id="標準庫重大變更" tabindex="-1">標準庫重大變更 <a class="header-anchor" href="#標準庫重大變更" aria-label="Permalink to &quot;標準庫重大變更&quot;">​</a></h2><h3 id="writergate-i-o-接口完全重構" tabindex="-1">Writergate：I/O 接口完全重構 <a class="header-anchor" href="#writergate-i-o-接口完全重構" aria-label="Permalink to &quot;Writergate：I/O 接口完全重構&quot;">​</a></h3><p>這是本次更新中<strong>最重大的破壞性更改</strong>，被社區稱為 &quot;Writergate&quot;：</p><ul><li><code>std.io.Reader</code> 和 <code>std.io.Writer</code> 接口被完全重新設計</li><li>新接口採用非泛型設計</li><li>緩衝區位於接口之上</li><li>旨在提高性能並減少不必要的拷貝</li><li><strong>需要大量代碼重寫</strong></li></ul><h3 id="格式化系統調整" tabindex="-1">格式化系統調整 <a class="header-anchor" href="#格式化系統調整" aria-label="Permalink to &quot;格式化系統調整&quot;">​</a></h3><p>格式化系統進行了重要調整：</p><ul><li>調用自定義 <code>format</code> 方法需要使用 <code>{f}</code> 格式說明符</li><li><code>format</code> 方法簽名簡化，移除了格式字符串和選項參數</li><li>格式化打印不再處理 Unicode</li><li>新增了更多格式化說明符</li></ul><h3 id="arraylist-非託管化" tabindex="-1"><code>ArrayList</code> 非託管化 <a class="header-anchor" href="#arraylist-非託管化" aria-label="Permalink to &quot;`ArrayList` 非託管化&quot;">​</a></h3><p>容器類型的重要變更：</p><ul><li><code>std.ArrayList</code> 現在默認採用非託管方式</li><li>開發者需要顯式提供分配器</li><li>與其他非託管容器保持一致</li><li>提供更好的內存管理控制</li></ul><h3 id="鏈表去泛型化" tabindex="-1">鏈表去泛型化 <a class="header-anchor" href="#鏈表去泛型化" aria-label="Permalink to &quot;鏈表去泛型化&quot;">​</a></h3><p>鏈表類型進行了重構，去除了泛型化設計。</p><h3 id="http-客戶端和服務器" tabindex="-1">HTTP 客戶端和服務器 <a class="header-anchor" href="#http-客戶端和服務器" aria-label="Permalink to &quot;HTTP 客戶端和服務器&quot;">​</a></h3><p>標準庫新增了 HTTP 支持，提供內置的 HTTP 客戶端和服務器功能。</p><h3 id="tls-客戶端" tabindex="-1">TLS 客戶端 <a class="header-anchor" href="#tls-客戶端" aria-label="Permalink to &quot;TLS 客戶端&quot;">​</a></h3><p>新增內置 TLS 支持，可以建立安全的 TLS 連接。</p><h3 id="環形緩衝區" tabindex="-1">環形緩衝區 <a class="header-anchor" href="#環形緩衝區" aria-label="Permalink to &quot;環形緩衝區&quot;">​</a></h3><p>新增了環形緩衝區類型，提供高效的循環緩衝區實現。</p><h3 id="移除-boundedarray" tabindex="-1">移除 BoundedArray <a class="header-anchor" href="#移除-boundedarray" aria-label="Permalink to &quot;移除 BoundedArray&quot;">​</a></h3><p><code>BoundedArray</code> 被移除，建議使用 <code>ArrayList</code> 或固定大小數組替代。</p><h2 id="構建系統改進" tabindex="-1">構建系統改進 <a class="header-anchor" href="#構建系統改進" aria-label="Permalink to &quot;構建系統改進&quot;">​</a></h2><h3 id="移除隱式根模塊" tabindex="-1">移除隱式根模塊 <a class="header-anchor" href="#移除隱式根模塊" aria-label="Permalink to &quot;移除隱式根模塊&quot;">​</a></h3><p>構建系統移除了對隱式根模塊的支持，現在需要在構建腳本中明確指定模塊；這提高了構建配置的清晰度和準確性。</p><h3 id="macos-文件系統監視" tabindex="-1">macOS 文件系統監視 <a class="header-anchor" href="#macos-文件系統監視" aria-label="Permalink to &quot;macOS 文件系統監視&quot;">​</a></h3><p>在 macOS 上新增了文件系統監視功能：</p><ul><li>能夠在文件更改時自動觸發重建</li><li>支持 <code>--watch</code> 和 <code>--debounce</code> 選項</li><li>顯著提高開發效率</li></ul><h3 id="web-界面和時間報告" tabindex="-1">Web 界面和時間報告 <a class="header-anchor" href="#web-界面和時間報告" aria-label="Permalink to &quot;Web 界面和時間報告&quot;">​</a></h3><p>構建系統現在支持 Web 界面和詳細的時間報告功能。</p><h3 id="模糊測試器" tabindex="-1">模糊測試器 <a class="header-anchor" href="#模糊測試器" aria-label="Permalink to &quot;模糊測試器&quot;">​</a></h3><p>Zig 0.15.1 集成了一個內置的模糊測試器：</p><ul><li>支持進程內模糊測試</li><li>提供 Web UI 界面</li><li>支持實時代碼覆蓋率顯示</li><li>可以快速發現代碼中的潛在問題</li></ul><h2 id="工具鏈更新" tabindex="-1">工具鏈更新 <a class="header-anchor" href="#工具鏈更新" aria-label="Permalink to &quot;工具鏈更新&quot;">​</a></h2><h3 id="llvm-20" tabindex="-1">LLVM 20 <a class="header-anchor" href="#llvm-20" aria-label="Permalink to &quot;LLVM 20&quot;">​</a></h3><p>升級到 LLVM 20，帶來了：</p><ul><li>更好的優化支持</li><li>新的目標架構支持</li><li>改進的調試信息生成</li><li>更好的 C++ 交互性</li></ul><h3 id="freebsd-和-netbsd-libc-支持" tabindex="-1">FreeBSD 和 NetBSD libc 支持 <a class="header-anchor" href="#freebsd-和-netbsd-libc-支持" aria-label="Permalink to &quot;FreeBSD 和 NetBSD libc 支持&quot;">​</a></h3><p>在交叉編譯時新增了對動態鏈接的 FreeBSD 和 NetBSD libc 的支持。</p><h3 id="glibc-2-42" tabindex="-1">glibc 2.42 <a class="header-anchor" href="#glibc-2-42" aria-label="Permalink to &quot;glibc 2.42&quot;">​</a></h3><p>升級到 glibc 2.42，並支持靜態鏈接本機 glibc。</p><h3 id="mingw-w64-更新" tabindex="-1">MinGW-w64 更新 <a class="header-anchor" href="#mingw-w64-更新" aria-label="Permalink to &quot;MinGW-w64 更新&quot;">​</a></h3><p>MinGW-w64 工具鏈得到了更新，進一步改進了對 Windows 的交叉編譯支持。</p><h3 id="zig-libc-和-zig-cc-增強" tabindex="-1">zig libc 和 zig cc 增強 <a class="header-anchor" href="#zig-libc-和-zig-cc-增強" aria-label="Permalink to &quot;zig libc 和 zig cc 增強&quot;">​</a></h3><p><code>zig libc</code> 和 <code>zig cc</code> 命令的功能得到了增強：</p><ul><li>更好的 GCC 兼容性</li><li>支持更多編譯選項</li><li>更清晰的錯誤報告</li></ul><h2 id="版本跳躍說明" tabindex="-1">版本跳躍說明 <a class="header-anchor" href="#版本跳躍說明" aria-label="Permalink to &quot;版本跳躍說明&quot;">​</a></h2><p>Zig 官方團隊選擇直接從 <code>0.14.0</code> 跳躍到 <code>0.15.1</code>，這一決策反映了：</p><ul><li>本次更新包含的重大變更數量之多</li><li>對編譯器性能的重要改進</li><li>標準庫接口的重大重構</li><li>為未來版本奠定更堅實的基礎</li></ul><h2 id="升級挑戰與機遇" tabindex="-1">升級挑戰與機遇 <a class="header-anchor" href="#升級挑戰與機遇" aria-label="Permalink to &quot;升級挑戰與機遇&quot;">​</a></h2><h3 id="主要挑戰" tabindex="-1">主要挑戰 <a class="header-anchor" href="#主要挑戰" aria-label="Permalink to &quot;主要挑戰&quot;">​</a></h3><ol><li><strong>Writergate</strong>：I/O 接口的完全重構需要重寫大量相關代碼</li><li><strong>移除 <code>usingnamespace</code></strong>：需要調整導入方式</li><li><strong>異步代碼調整</strong>：需要移除 async/await 使用</li><li><strong>ArrayList 變更</strong>：需要調整容器使用方式</li></ol><h3 id="主要機遇" tabindex="-1">主要機遇 <a class="header-anchor" href="#主要機遇" aria-label="Permalink to &quot;主要機遇&quot;">​</a></h3><ol><li><strong>編譯速度提升</strong>：5 倍的調試編譯速度改進</li><li><strong>更清晰的代碼</strong>：移除隱式行為，提高代碼可讀性</li><li><strong>更好的性能</strong>：新的 I/O 接口設計更高效</li><li><strong>開發效率</strong>：文件系統監視功能和模糊測試器</li></ol><h2 id="社區影響" tabindex="-1">社區影響 <a class="header-anchor" href="#社區影響" aria-label="Permalink to &quot;社區影響&quot;">​</a></h2><p>這次更新對 Zig 社區產生了重要影響：</p><ul><li><strong>學習曲線</strong>：新用戶需要適應新的接口設計</li><li><strong>遷移工作</strong>：現有項目需要進行大量調整</li><li><strong>性能收益</strong>：編譯速度的顯著提升改善開發體驗</li><li><strong>生態系統</strong>：庫作者需要更新以適配新接口</li></ul><h2 id="技術債務清理" tabindex="-1">技術債務清理 <a class="header-anchor" href="#技術債務清理" aria-label="Permalink to &quot;技術債務清理&quot;">​</a></h2><p>本次更新體現了 Zig 團隊對技術債務的積極清理：</p><ul><li>移除了有爭議的 <code>usingnamespace</code> 特性</li><li>重構了性能不佳的 I/O 接口</li><li>統一了容器類型的設計理念</li><li>為未來的語言演進奠定堅實基礎</li></ul><h2 id="未來展望" tabindex="-1">未來展望 <a class="header-anchor" href="#未來展望" aria-label="Permalink to &quot;未來展望&quot;">​</a></h2><p><code>0.15.1</code> 為 Zig 的未來發展奠定了重要基礎：</p><ul><li><strong>編譯性能</strong>：為大型項目開發提供更好支持</li><li><strong>接口設計</strong>：更一致、更高效的標準庫</li><li><strong>開發體驗</strong>：更快的編譯和更好的工具支持</li><li><strong>語言穩定性</strong>：移除不穩定特性，為 1.0 做準備</li></ul><h2 id="路線圖" tabindex="-1">路線圖 <a class="header-anchor" href="#路線圖" aria-label="Permalink to &quot;路線圖&quot;">​</a></h2><h3 id="i-o-作為接口" tabindex="-1">I/O 作為接口 <a class="header-anchor" href="#i-o-作為接口" aria-label="Permalink to &quot;I/O 作為接口&quot;">​</a></h3><p>I/O 系統將繼續作為接口進行發展和完善，為未來的異步編程模型做準備。</p><h2 id="建議" tabindex="-1">建議 <a class="header-anchor" href="#建議" aria-label="Permalink to &quot;建議&quot;">​</a></h2><p>對於 Zig 開發者：</p><ol><li><strong>謹慎升級</strong>：在測試環境中充分驗證</li><li><strong>分步遷移</strong>：逐步調整代碼以適配新接口</li><li><strong>充分利用性能優勢</strong>：積極採用有關編譯速度的改進</li><li><strong>關注社區動態</strong>：參與社區討論，分享遷移經驗和最佳實踐</li></ol><p><code>0.15.1</code> 是 Zig 發展歷程中的一個重要里程碑，雖然帶來了較多的破壞性變更，但為語言的長期發展和性能提升奠定了堅實的基礎。這標誌著語言穩定化的最後階段，為 1.0 版本的正式發佈做好了充分準備。</p>',98)]))}const p=e(r,[["render",t]]);export{b as __pageData,p as default};
